    rows = list(reader)

    print('File: outputs/t02_eurostat_raw.csv')
    print('Columns:', header)
    print('Number of rows:', len(rows))
    print()

    # Verify no duplicate city_id/year/indicator_id combinations
    seen = set()
    duplicates = []
    for i, row in enumerate(rows):
        key = (row['city_id'], row['year'], row['indicator_id'])
        if key in seen:
            duplicates.append((i, key, row))
        seen.add(key)

    if duplicates:
        print('DUPLICATES FOUND!')
        for dup in duplicates[:5]:
            print(dup)
    else:
        print('No duplicate city_id/year/indicator_id combinations')

    # Verify no RFC 4180 issues
    has_issues = False
    for i, row in enumerate(rows):
        if i > 0:
            for j, field in enumerate(row):
                if ',' in field or '\"' in field or '\n' in field:
                    has_issues = True
                    print(f'RFC 4180 issue at row {i}, col {j}: {field[:50]}...')
                    break
            else:
                continue
            break

